'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import { config, DEDICATION_KEYS } from '@/content/config';
import { TEHILLIM_MAX } from '@/lib/pledges';
import RotatingSaying from '@/components/RotatingSaying';
import HebrewKeyboard from '@/components/HebrewKeyboard';
import PrintCard from '@/components/PrintCard';
import ZmanimCard from '@/components/ZmanimCard';
import ShiurPlayer from '@/components/ShiurPlayer';
import SuggestionBox from '@/components/SuggestionBox';
import MiShebeirach from '@/components/MiShebeirach';
import NamesCard from '@/components/NamesCard';
import CandleChain from '@/components/CandleChain';

/** Print one card without the other landing on the page too. */
function printOnly(id) {
  document.body.setAttribute('data-print', id);
  window.print();
  setTimeout(() => document.body.removeAttribute('data-print'), 500);
}

const { afterPresets, afterExtraDefault, afterExtraOptions, beforeOptions, min: FIELD_MIN, max: FIELD_MAX } =
  config.pledge;

export default function Home() {
  const [unlocked, setUnlocked] = useState(false);
  const [unlocking, setUnlocking] = useState(false);
  const [gateInput, setGateInput] = useState('');
  const [gateError, setGateError] = useState('');

  useEffect(() => {
    if (sessionStorage.getItem('tsb_unlocked') === '1') setUnlocked(true);
  }, []);

  async function submitGate(e) {
    e.preventDefault();
    if (unlocking) return;
    const code = gateInput.trim();
    if (!code) return;

    setUnlocking(true);
    setGateError('');
    try {
      const res = await fetch('/api/gate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code }),
      });
      const data = await res.json();
      if (data.ok) {
        sessionStorage.setItem('tsb_unlocked', '1');
        sessionStorage.setItem('tsb_community_code', code);
        if (data.token) sessionStorage.setItem('tsb_gate_token', data.token);
        // A correct code earns the tumbler run and the doors parting before
        // the board appears. Reduced motion goes straight in.
        if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
          setUnlocked(true);
          return;
        }
        setTimeout(() => setUnlocked(true), 1150);
      } else {
        setGateError('That code is not correct.');
        setUnlocking(false);
      }
    } catch {
      setGateError('Could not reach the server. Please try again.');
      setUnlocking(false);
    }
  }

  if (!unlocked) {
    return (
      <main className="wrap gate-wrap">
        <div className="hero rise">
          <div className="mark" />
          <h1>Tosfos Shabbos</h1>
          <p className="lede">A board of zechuyos — take on a little more Shabbos.</p>
        </div>

        {/* The shul door. Everything on it is decorative EXCEPT the posted
            note: that's the hint for the combination, worded the way a shul
            posts it on the door. The digits themselves are never rendered. */}
        <div className={`door rise-2 ${unlocking ? 'open' : ''}`}>
          <div className="door-frame" aria-hidden="true">
            <div className="door-lintel" dir="rtl" lang="he">מה טובו אהליך יעקב</div>
            <div className="door-leaves">
              <div className="leaf" />
              <div className="leaf" />
            </div>
            <span className="mezuzah" />
          </div>
          <div className="door-note">
            <div className="note-he" dir="rtl" lang="he">
              שני לוחות הברית · אבות · חמישה חומשי תורה
            </div>
            <div className="note-en">Shnei Luchos HaBris · Avos · Chamishah Chumshei Torah</div>
          </div>
        </div>

        <form className="panel gate-panel rise-3" onSubmit={submitGate}>
          <div className="gate-lock">
            {/* The dial turns a little as digits are entered — decoration only. */}
            <div className={`dial ${unlocking ? 'unlocking' : ''}`} aria-hidden="true">
              <div
                className="dial-ring"
                style={{ transform: `rotate(${gateInput.length * -47}deg)` }}
              />
              <div className="dial-knob" />
              <span className="dial-pointer" />
            </div>
            <div className="gate-field">
              <label htmlFor="gate" dir="rtl" lang="he">זה השער לה׳ צדיקים יבואו בו</label>
              <input
                id="gate" type="password" inputMode="numeric" autoComplete="off"
                value={gateInput} onChange={(e) => setGateInput(e.target.value)} placeholder="• • •" autoFocus
              />
            </div>
          </div>
          {gateError && <div className="msg err">{gateError}</div>}
          <button className="btn" type="submit" disabled={unlocking}>
            {unlocking ? 'Opening…' : 'Enter'}
          </button>
        </form>
      </main>
    );
  }

  return <Board />;
}

function Board() {
  const [groups, setGroups] = useState([]);
  const [featured, setFeatured] = useState(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [showNames, setShowNames] = useState(false);
  const [loading, setLoading] = useState(true);
  const formRef = useRef(null);
  const [prefill, setPrefill] = useState(null);

  // The Admin link is only shown to someone already signed in as admin.
  // /admin and every admin API stay ADMIN_CODE-protected regardless.
  useEffect(() => {
    setIsAdmin(Boolean(sessionStorage.getItem('tsb_admin_code')));
  }, []);

  const loadWall = useCallback(async () => {
    try {
      const token = sessionStorage.getItem('tsb_gate_token') || '';
      const res = await fetch('/api/pledges', {
        cache: 'no-store',
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      });
      if (!res.ok) return;
      const data = await res.json();
      setGroups(data.groups || []);
      setFeatured(data.featured || null);
    } catch {
      /* keep prior state */
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadWall();
    const t = setInterval(loadWall, 30000);
    return () => clearInterval(t);
  }, [loadWall]);

  function handleRePledge(group) {
    setPrefill({
      refuahName: group.refuahName,
      refuahNameEnglish: group.refuahNameEnglish || '',
      refuahMotherName: group.refuahMotherName || '',
      refuahRelation: group.refuahRelation || 'ben',
      dedicationType: group.dedicationType || 'refuah',
      _n: Date.now(),
    });
    formRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  // Counted minutes are extra only — the after-Shabbos baseline never counts.
  const total = groups.reduce((s, g) => s + g.totalMinutesPerWeek, 0);
  const totalBefore = groups.reduce((s, g) => s + (g.beforeMinutes || 0), 0);
  const totalOnTop = groups.reduce((s, g) => s + (g.afterExtraMinutes || 0), 0);

  return (
    <main className="wrap">
      <div className="hero rise">
        <div className="mark" />
        <h1>Tosfos Shabbos</h1>
        <p className="lede">
          Take on a little more Shabbos — before it comes in, after it goes out — as a zechus.
        </p>
      </div>

      <div className="rise-2"><ShiurPlayer /></div>

      <div className="rise-2"><ZmanimCard /></div>

      {featured?.refuahName && (
        <section className="spotlight rise-2" aria-label="Featured urgent refuah">
          <div className="sp-kicker">Please daven for</div>
          <div className="sp-name" dir="auto">{featured.refuahName}</div>
          {featured.refuahNameEnglish && <div className="sp-en">{featured.refuahNameEnglish}</div>}
          {featured.note && <div className="sp-note">{featured.note}</div>}
          <button
            className="btn ghost"
            onClick={() => handleRePledge({
              refuahName: featured.refuahName,
              refuahNameEnglish: featured.refuahNameEnglish,
              dedicationType: featured.dedicationType || 'refuah',
            })}
          >
            + Pledge for this name
          </button>
        </section>
      )}

      <div className="rise-2" style={{ marginTop: 28 }}>
        <RotatingSaying start={0} interval={9000} />
      </div>

      {total > 0 && (
        <section className="tally rise-3" aria-label="Community total">
          <div className="tally-main">
            <CountUp value={total} />
            <span className="tally-unit">Together, the kehillah is keeping</span>
          </div>
          <div className="tally-sub">
            extra minutes of Shabbos — a collective zechus for all{' '}
            <b>{groups.length}</b> {groups.length === 1 ? 'name' : 'names'}
          </div>
          <div className="tally-split">
            <span><b>{totalBefore}</b> early</span>
            <span className="tally-dot" aria-hidden="true">·</span>
            <span><b>{totalOnTop}</b> on top</span>
          </div>
          <CandleChain count={groups.length} />
        </section>
      )}

      <div ref={formRef}>
        <Reveal>
          <PledgeForm prefill={prefill} onCreated={loadWall} communityNames={groups.length} />
        </Reveal>
      </div>

      <section className="wall">
        <Reveal delay={60}>
          <div className="wall-head">
            <h2>The Board</h2>
          </div>
        </Reveal>

        {loading ? (
          <div role="status" aria-label="Lighting the board">
            <SkeletonCard />
            <SkeletonCard delay={110} />
          </div>
        ) : groups.length === 0 ? (
          <div className="panel">
            <RotatingSaying start={3} interval={0} />
            <div className="empty">Be the first to take on Tosfos Shabbos.</div>
          </div>
        ) : (
          groups.map((g, i) => (
            <WallCard
              key={`${g.refuahName}-${g.dedicationType}`}
              group={g}
              rank={i}
              maxMinutes={groups[0]?.totalMinutesPerWeek || 1}
              communityMinutes={total}
              communityNames={groups.length}
              onRePledge={() => handleRePledge(g)}
            />
          ))
        )}
      </section>

      {groups.length > 0 && (
        <>
          <div className="toolbar no-print">
            <button type="button" className="linkbtn" onClick={() => setShowNames((v) => !v)}>
              📜 {showNames ? 'Hide' : 'Print'} names to daven for
            </button>
          </div>
          {showNames && (
            <>
              <NamesCard groups={groups} />
              <div className="toolbar no-print">
                <button className="btn ghost" onClick={() => printOnly('names')}>🖨 Print this list</button>
              </div>
            </>
          )}
        </>
      )}

      <Reveal delay={60}>
        <SuggestionBox />
      </Reveal>

      {isAdmin && (
        <div className="toolbar no-print">
          <a className="linkbtn" href="/admin">Admin</a>
        </div>
      )}
    </main>
  );
}

/** Ghost of a wall card while the board loads — same footprint, gold shimmer. */
function SkeletonCard({ delay = 0 }) {
  return (
    <div className="card" style={{ animationDelay: `${delay}ms` }} aria-hidden="true">
      <div className="skel-row">
        <div>
          <div className="skel skel-kicker" />
          <div className="skel skel-name" />
        </div>
        <div className="skel skel-min" />
      </div>
      <div className="skel skel-bar" />
      <div className="skel-pills">
        <div className="skel skel-pill" />
        <div className="skel skel-pill" />
      </div>
    </div>
  );
}

/** Gentle count-up, used for the community tally and each card's minutes. */
function CountUp({ value, className = 'tally-num' }) {
  // Default to the real value so the number is correct even if we never animate.
  const [shown, setShown] = useState(value);
  useEffect(() => {
    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
    // In a background tab requestAnimationFrame is suspended, so skip the
    // animation entirely rather than risk showing a stale 0.
    if (reduce || document.hidden) { setShown(value); return undefined; }

    let raf;
    let done = false;
    const dur = 1350;
    const start = performance.now();
    const tick = (t) => {
      const p = Math.min(1, (t - start) / dur);
      const eased = 1 - Math.pow(1 - p, 3);
      setShown(Math.round(value * eased));
      if (p < 1) raf = requestAnimationFrame(tick);
      else done = true;
    };
    setShown(0);
    raf = requestAnimationFrame(tick);
    // Safety net: if rAF is throttled mid-flight, snap to the final value.
    const fallback = setTimeout(() => { if (!done) setShown(value); }, dur + 400);

    return () => { cancelAnimationFrame(raf); clearTimeout(fallback); };
  }, [value]);
  return <span className={className}>{shown.toLocaleString()}</span>;
}

/**
 * Fade + rise a section in when it first scrolls into view. The class is added
 * once and kept — content must never fade back out while someone reads it.
 * Reduced motion (and any browser without IntersectionObserver) shows the
 * section immediately.
 */
function Reveal({ children, delay = 0 }) {
  const ref = useRef(null);
  const [seen, setSeen] = useState(false);
  useEffect(() => {
    const el = ref.current;
    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
    if (!el || reduce || typeof IntersectionObserver === 'undefined') { setSeen(true); return undefined; }
    // A healthy observer always reports the INITIAL state within a frame or
    // two, even for off-screen elements. If it never calls back at all, the
    // environment has IO suspended — reveal rather than stay invisible.
    let reported = false;
    const io = new IntersectionObserver(
      ([entry]) => {
        reported = true;
        if (entry.isIntersecting) { setSeen(true); io.disconnect(); }
      },
      { rootMargin: '0px 0px -8% 0px', threshold: 0.08 }
    );
    io.observe(el);
    const failsafe = setTimeout(() => { if (!reported) setSeen(true); }, 1500);
    return () => { io.disconnect(); clearTimeout(failsafe); };
  }, []);
  return (
    <div
      ref={ref}
      className={`reveal ${seen ? 'in' : ''}`}
      style={delay ? { transitionDelay: `${delay}ms` } : undefined}
    >
      {children}
    </div>
  );
}

function PledgeForm({ prefill, onCreated, communityNames }) {
  const [refuahName, setRefuahName] = useState('');
  const [refuahNameEnglish, setRefuahNameEnglish] = useState('');
  const [motherName, setMotherName] = useState('');
  const [relation, setRelation] = useState('ben');
  const [dedicationType, setDedicationType] = useState('refuah');
  const [tehillim, setTehillim] = useState('');
  const [nameLang, setNameLang] = useState('he'); // 'he' | 'en'

  // After Shabbos
  const [afterOn, setAfterOn] = useState(true);
  const [afterBase, setAfterBase] = useState(60);
  const [afterCustom, setAfterCustom] = useState(90);
  const [afterExtra, setAfterExtra] = useState(afterExtraDefault);

  // Before Shabbos
  const [beforeOn, setBeforeOn] = useState(false);
  const [beforeMin, setBeforeMin] = useState(10);

  const [weeks, setWeeks] = useState(1);
  const [pledgerName, setPledgerName] = useState('');
  const [email, setEmail] = useState('');
  const [hp, setHp] = useState('');
  // Which Hebrew field the on-screen keyboard is currently driving.
  const [kbdFor, setKbdFor] = useState(null); // 'name' | 'mother' | null
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState(null);
  const [submitted, setSubmitted] = useState(null);

  const nameRef = useRef(null);
  const motherRef = useRef(null);
  const caretRef = useRef(null);

  useEffect(() => {
    if (prefill) {
      setRefuahName(prefill.refuahName || '');
      setRefuahNameEnglish(prefill.refuahNameEnglish || '');
      setMotherName(prefill.refuahMotherName || '');
      setRelation(prefill.refuahRelation || 'ben');
      setDedicationType(prefill.dedicationType || 'refuah');
      // Joining a zechus copies the NAME, never someone else's kabbalah.
      setTehillim('');
      setSubmitted(null);
      setMsg(null);
    }
  }, [prefill]);

  const kbdRef = kbdFor === 'mother' ? motherRef : nameRef;
  const kbdValue = kbdFor === 'mother' ? motherName : refuahName;
  const setKbdValue = kbdFor === 'mother' ? setMotherName : setRefuahName;

  // Restore caret after keyboard-driven edits, in whichever field is active.
  useEffect(() => {
    if (caretRef.current != null && kbdRef.current) {
      kbdRef.current.focus();
      const p = caretRef.current;
      kbdRef.current.setSelectionRange(p, p);
      caretRef.current = null;
    }
  }, [refuahName, motherName, kbdRef]);

  function insertAtCaret(ch) {
    const el = kbdRef.current;
    const start = el?.selectionStart ?? kbdValue.length;
    const end = el?.selectionEnd ?? kbdValue.length;
    caretRef.current = start + ch.length;
    setKbdValue(kbdValue.slice(0, start) + ch + kbdValue.slice(end));
  }
  function backspace() {
    const el = kbdRef.current;
    const start = el?.selectionStart ?? kbdValue.length;
    const end = el?.selectionEnd ?? kbdValue.length;
    if (start === end) {
      if (start === 0) return;
      caretRef.current = start - 1;
      setKbdValue(kbdValue.slice(0, start - 1) + kbdValue.slice(end));
    } else {
      caretRef.current = start;
      setKbdValue(kbdValue.slice(0, start) + kbdValue.slice(end));
    }
  }

  const afterBaseValue = afterBase === 'custom' ? Number(afterCustom) : afterBase;
  const effAfterBase = afterOn ? afterBaseValue : null;
  const effAfterExtra = afterOn ? Number(afterExtra) || 0 : 0;
  const effBefore = beforeOn ? Number(beforeMin) || 0 : 0;
  // Only genuinely added minutes count — the base is what they keep anyway.
  const runningTotal = (effBefore || 0) + (effAfterExtra || 0);

  async function submit(e) {
    e.preventDefault();
    setMsg(null);

    if (!refuahName.trim()) {
      setMsg({ type: 'err', text: 'Please enter the name for the dedication.' });
      return;
    }
    if (runningTotal === 0) {
      setMsg({
        type: 'err',
        text: 'Add at least a minute — on top of your usual end time, or before Shabbos.',
      });
      return;
    }
    if (afterOn && afterBase === 'custom') {
      const v = Number(afterCustom);
      if (!Number.isInteger(v) || v < FIELD_MIN || v > FIELD_MAX) {
        setMsg({ type: 'err', text: `Custom minutes must be a whole number between ${FIELD_MIN} and ${FIELD_MAX}.` });
        return;
      }
    }

    setBusy(true);
    try {
      const res = await fetch('/api/pledges', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          communityCode: sessionStorage.getItem('tsb_community_code') || '',
          refuahName: refuahName.trim(),
          refuahNameEnglish: refuahNameEnglish.trim() || null,
          refuahMotherName: motherName.trim() || null,
          refuahRelation: relation,
          dedicationType,
          tehillimChapters: tehillim.trim() || null,
          beforeMinutes: effBefore,
          afterBaseMinutes: effAfterBase,
          afterExtraMinutes: effAfterExtra,
          weeks: Number(weeks),
          pledgerName: pledgerName.trim() || null,
          email: email.trim() || null,
          hp_field: hp,
        }),
      });
      const data = await res.json();
      if (!res.ok) {
        setMsg({ type: 'err', text: data.error || 'Something went wrong.' });
      } else {
        setSubmitted({
          refuahName: refuahName.trim(),
          refuahNameEnglish: refuahNameEnglish.trim() || null,
          refuahMotherName: motherName.trim() || null,
          refuahRelation: relation,
          dedicationType,
          tehillimChapters: tehillim.trim() || null,
          beforeMinutes: effBefore,
          afterBaseMinutes: effAfterBase || 0,
          afterExtraMinutes: effAfterExtra,
          weeks: Number(weeks),
          sayingIndex: Math.abs(refuahName.length + runningTotal + weeks) % 997,
        });
        setMsg(null);
        setKbdFor(null);
        setPledgerName('');
        setEmail('');
        onCreated?.();
      }
    } catch {
      setMsg({ type: 'err', text: 'Network error. Please try again.' });
    } finally {
      setBusy(false);
    }
  }

  function makeAnother() {
    setSubmitted(null);
    setRefuahName('');
    setRefuahNameEnglish('');
    // A kabbalah belongs to the pledge it was made on — don't carry it over.
    setTehillim('');
  }

  const dedList = DEDICATION_KEYS.map((k) => ({ key: k, ...config.dedications[k] }));

  return (
    <>
      <form className="panel rise-3" onSubmit={submit} noValidate>
        <h2>Make a Pledge</h2>
        <p className="sub">A little more Shabbos, in someone’s zechus.</p>

        <label>Dedication</label>
        <div className="segment">
          {dedList.map((d) => (
            <div
              key={d.key}
              className={`seg ${dedicationType === d.key ? 'active' : ''}`}
              onClick={() => setDedicationType(d.key)}
              role="button" tabIndex={0}
              onKeyDown={(e) => e.key === 'Enter' && setDedicationType(d.key)}
            >
              {d.label}
              <small>{d.hint}</small>
            </div>
          ))}
        </div>

        <label htmlFor="refuahName">Name *</label>
        <div className="segment" style={{ marginBottom: 10 }}>
          {[{ k: 'he', l: 'עברית' }, { k: 'en', l: 'English' }].map((r) => (
            <div
              key={r.k}
              className={`seg ${nameLang === r.k ? 'active' : ''}`}
              onClick={() => setNameLang(r.k)}
              role="button" tabIndex={0}
              onKeyDown={(e) => e.key === 'Enter' && setNameLang(r.k)}
            >
              {r.l}
            </div>
          ))}
        </div>
        <input
          id="refuahName" ref={nameRef} type="text"
          dir={nameLang === 'he' ? 'rtl' : 'ltr'}
          className={nameLang === 'he' ? 'he-input' : ''}
          value={refuahName} onChange={(e) => setRefuahName(e.target.value)}
          placeholder={nameLang === 'he' ? 'פלוני' : 'e.g. Ploni ben Plonis'} required
        />
        {nameLang === 'he' && (
          <button
            type="button" className="kbd-toggle"
            onClick={() => setKbdFor((v) => (v === 'name' ? null : 'name'))}
          >
            ⌨ {kbdFor === 'name' ? 'Hide Hebrew keyboard' : 'Hebrew keyboard'}
          </button>
        )}
        {nameLang === 'he' && kbdFor === 'name' && (
          <HebrewKeyboard
            onInsert={insertAtCaret} onBackspace={backspace}
            onSpace={() => insertAtCaret(' ')} onClose={() => setKbdFor(null)}
          />
        )}

        {/* Mother's name — what the Mi Shebeirach needs. */}
        <label htmlFor="motherName">
          Mother&apos;s name{' '}
          <span className="opt">
            {dedicationType === 'refuah' ? '— for the Mi Shebeirach' : '— optional'}
          </span>
        </label>
        <div className="relation-row">
          <div className="segment relation-seg">
            {[{ k: 'ben', l: 'בן' }, { k: 'bas', l: 'בת' }].map((r) => (
              <div
                key={r.k}
                className={`seg ${relation === r.k ? 'active' : ''}`}
                onClick={() => setRelation(r.k)}
                role="button" tabIndex={0}
                onKeyDown={(e) => e.key === 'Enter' && setRelation(r.k)}
              >
                <span className="he-input" style={{ fontSize: '1.2rem' }}>{r.l}</span>
              </div>
            ))}
          </div>
          <input
            id="motherName" ref={motherRef} type="text" dir="rtl" className="he-input"
            value={motherName} onChange={(e) => setMotherName(e.target.value)}
            placeholder="פלונית"
          />
        </div>
        <button
          type="button" className="kbd-toggle"
          onClick={() => setKbdFor((v) => (v === 'mother' ? null : 'mother'))}
        >
          ⌨ {kbdFor === 'mother' ? 'Hide Hebrew keyboard' : "Hebrew keyboard for mother's name"}
        </button>
        {kbdFor === 'mother' && (
          <HebrewKeyboard
            onInsert={insertAtCaret} onBackspace={backspace}
            onSpace={() => insertAtCaret(' ')} onClose={() => setKbdFor(null)}
          />
        )}
        {refuahName && motherName && (
