        </div>

        <label htmlFor="weeks">For how many weeks?</label>
        <select id="weeks" value={weeks} onChange={(e) => setWeeks(Number(e.target.value))}>
          {[1, 2, 3, 4].map((w) => <option key={w} value={w}>{w} {w === 1 ? 'week' : 'weeks'}</option>)}
        </select>

        <label htmlFor="pledgerName">Your name <span className="opt">— optional</span></label>
        <input id="pledgerName" type="text" value={pledgerName} onChange={(e) => setPledgerName(e.target.value)} placeholder="Shown on the board only if you add it" />

        <label htmlFor="email">Email <span className="opt">— optional, private</span></label>
