        <div className="hint">Kept private — never shown on the board.</div>

        <div className="hp" aria-hidden="true">
          <label htmlFor="hp_field">Leave this field empty</label>
          <input id="hp_field" name="hp_field" type="text" tabIndex={-1} autoComplete="off" value={hp} onChange={(e) => setHp(e.target.value)} />
