      </form>

      {submitted && (
        <>
          <div className="panel rise no-print" style={{ marginTop: 16 }}>
            <div className="msg ok">Tzku l’mitzvos! Your pledge is on the board.</div>
            <div className="success-actions">
              <button className="btn ghost" onClick={() => printOnly('card')}>🖨 Print Shabbos-table card</button>
              <button className="btn ghost" onClick={makeAnother}>Make another pledge</button>
