              <MiShebeirach
                name={submitted.refuahName}
                motherName={submitted.refuahMotherName}
                relation={submitted.refuahRelation}
                tehillim={submitted.tehillimChapters}
                communityNames={communityNames}
              />
            )}
          </div>
          <PrintCard pledge={submitted} sayingIndex={submitted.sayingIndex} />
        </>
      )}
    </>
  );
}

function WallCard({ group, rank, maxMinutes, communityMinutes, communityNames, onRePledge }) {
  const countdown = useCountdown(group.nearestEnd);
  const ded = config.dedications[group.dedicationType] || config.dedications.refuah;
  const before = group.beforeMinutes || 0;
  const onTop = group.afterExtraMinutes || 0;
  const share = maxMinutes > 0 ? Math.max(6, Math.round((group.totalMinutesPerWeek / maxMinutes) * 100)) : 0;
  // Baselines differ per person, so show the range as context — never summed.
  const baseline =
    group.baselineMin == null
      ? null
      : group.baselineMin === group.baselineMax
        ? `${group.baselineMin}m`
        : `${group.baselineMin}–${group.baselineMax}m`;

  return (
    <div className="card" style={{ animationDelay: `${Math.min(rank * 70, 420)}ms` }}>
      <div className="card-top">
        <div>
          <div className="dedication">{ded.prefix}</div>
          <div className="name" dir="auto">{group.displayName || group.refuahName}</div>
          {group.refuahNameEnglish && <div className="name-en">{group.refuahNameEnglish}</div>}
        </div>
        <div className="minutes">
          <b><CountUp value={group.totalMinutesPerWeek} className="" /></b>
          <small>extra min / week</small>
        </div>
      </div>

      {/* proportional glow bar */}
      <div className="card-bar" aria-hidden="true"><span style={{ width: `${share}%` }} /></div>

      <div className="ends-row">
        {before > 0 && <span className="end-pill before">🕯 +{before} early</span>}
        {onTop > 0 && <span className="end-pill after">✦ +{onTop} late</span>}
        {baseline && <span className="end-pill baseline">holds til {baseline}</span>}
        <span className="end-pill count">{group.pledgeCount} {group.pledgeCount === 1 ? 'pledge' : 'pledges'}</span>
      </div>

      {group.pledgers?.length > 0 && <div className="pledgers">With {group.pledgers.join(', ')}</div>}

      {communityMinutes > 0 && communityNames > 1 && (
        <div className="community-note">
          Held b&rsquo;zchus <b>{communityNames}</b> names &amp;{' '}
          <b>{communityMinutes.toLocaleString()}</b> collective minutes of Shabbos
        </div>
      )}

      {/* Only the Tehillim actually taken on for this name — nothing if none. */}
      {group.tehillim?.length > 0 && (
        <div className="card-tehillim">
          <span className="ct-label">Tehillim</span>
          {group.tehillim.map((t, i) => (
            <span className="ct-item" key={`${t.text}-${i}`}>
              {t.text}
              {t.pledger && <span className="ct-by"> — {t.pledger}</span>}
            </span>
          ))}
        </div>
      )}

      <div className="card-bottom">
        <span className="countdown">
          {countdown ? <>Nearest ends in <b>{countdown}</b></> : <>Ended</>}
        </span>
        <button className="btn ghost no-print" onClick={onRePledge}>+ Join this zechus</button>
      </div>
    </div>
  );
}

function useCountdown(iso) {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 60000);
    return () => clearInterval(t);
  }, []);
  if (!iso) return null;
  let diff = new Date(iso).getTime() - now;
  if (diff <= 0) return null;
  const d = Math.floor(diff / 86400000); diff -= d * 86400000;
  const h = Math.floor(diff / 3600000); diff -= h * 3600000;
  const m = Math.floor(diff / 60000);
  if (d > 0) return `${d}d ${h}h`;
  if (h > 0) return `${h}h ${m}m`;
  return `${m}m`;
}

