// A printable Shabbos-table card shown after a successful pledge. The on-screen
// preview is styled light (parchment); @media print hides everything else so
// only this card prints.
export default function PrintCard({ pledge, sayingIndex = 0 }) {
  if (!pledge) return null;
  const ded = config.dedications[pledge.dedicationType] || config.dedications.refuah;
  const saying = sayingAt(sayingIndex);

  const before = pledge.beforeMinutes || 0;
  const base = pledge.afterBaseMinutes || 0;
  const extra = pledge.afterExtraMinutes || 0;
  // Counted total is extra only; the base is shown purely as context.
  const total = before + extra;

  return (
    <div className="print-card" id="print-card">
      <div className="pc-foil" />
      <div className="pc-body">
        <div className="pc-kicker">Tosfos Shabbos</div>
