              <span className="pc-end-lbl">Before Shabbos</span>
              <span className="pc-end-val">+{before} min early</span>
            </div>
          )}
          {extra > 0 && (
            <div className="pc-end">
              <span className="pc-end-lbl">After Shabbos</span>
