import HebrewKeyboard from '@/components/HebrewKeyboard';

export default function AdminPage() {
  const [adminCode, setAdminCode] = useState('');
  const [authed, setAuthed] = useState(false);
  const [pledges, setPledges] = useState([]);
  const [featured, setFeatured] = useState(null);
  const [suggestions, setSuggestions] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [tab, setTab] = useState('stats');
  const [editing, setEditing] = useState(null); // pledge id being edited

  useEffect(() => {
    const saved = sessionStorage.getItem('tsb_admin_code');
    if (saved) { setAdminCode(saved); setAuthed(true); }
  }, []);

  const load = useCallback(async (code) => {
    const useCode = code ?? adminCode;
    setLoading(true); setError('');
    try {
      const res = await fetch('/api/admin', { headers: { 'x-admin-code': useCode }, cache: 'no-store' });
      if (res.status === 401) {
        setError('Wrong admin code.'); setAuthed(false);
        sessionStorage.removeItem('tsb_admin_code');
        return false;
      }
      const data = await res.json();
      setPledges(data.pledges || []);
      setFeatured(data.featured || null);
      setSuggestions(data.suggestions || []);
      return true;
    } catch {
      setError('Could not load pledges.'); return false;
    } finally { setLoading(false); }
  }, [adminCode]);

  useEffect(() => { if (authed) load(); }, [authed, load]);

  async function submitLogin(e) {
    e.preventDefault();
    const ok = await load(adminCode);
    if (ok) { sessionStorage.setItem('tsb_admin_code', adminCode); setAuthed(true); }
  }

  function signOut() {
    sessionStorage.removeItem('tsb_admin_code');
    setAuthed(false); setAdminCode(''); setPledges([]);
  }

  async function post(payload) {
    const res = await fetch('/api/admin', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ adminCode, ...payload }),
    });
    if (!res.ok) {
      const d = await res.json().catch(() => ({}));
      throw new Error(d.error || 'Request failed.');
    }
    return res.json();
  }

  async function moderate(id, status) {
    setError('');
    try {
      await post({ action: 'moderate', id, status });
      setPledges((prev) => prev.map((p) => (p.id === id ? { ...p, status } : p)));
    } catch (e) { setError(e.message); }
  }

  const stats = useAnalytics(pledges);

  if (!authed) {
    return (
      <main className="wrap gate-wrap">
        <div className="hero rise">
          <div className="mark" />
          <h1>Admin</h1>
          <p className="lede">Enter the admin code to continue.</p>
        </div>
        <form className="panel rise-2" onSubmit={submitLogin}>
          <label htmlFor="adminCode">Admin code</label>
          <input id="adminCode" type="password" autoComplete="off" value={adminCode} onChange={(e) => setAdminCode(e.target.value)} autoFocus />
          {error && <div className="msg err">{error}</div>}
          <button className="btn" type="submit">Sign in</button>
        </form>
        <div className="toolbar"><a className="linkbtn" href="/">← Back to the board</a></div>
      </main>
    );
  }

  return (
    <main className="wrap">
      <div className="hero rise">
        <div className="mark" />
        <h1>Admin</h1>
      </div>

      <div className="tabs">
        <button className={`tab ${tab === 'stats' ? 'active' : ''}`} onClick={() => setTab('stats')}>Analytics</button>
        <button className={`tab ${tab === 'queue' ? 'active' : ''}`} onClick={() => setTab('queue')}>
          Queue <span className="tab-count">{pledges.length}</span>
        </button>
        <button className={`tab ${tab === 'suggestions' ? 'active' : ''}`} onClick={() => setTab('suggestions')}>
          Suggestions
          {suggestions.filter((s) => s.status === 'new').length > 0 && (
            <span className="tab-badge">{suggestions.filter((s) => s.status === 'new').length}</span>
          )}
        </button>
        <button className={`tab ${tab === 'whatsapp' ? 'active' : ''}`} onClick={() => setTab('whatsapp')}>WhatsApp</button>
        <button className={`tab ${tab === 'tools' ? 'active' : ''}`} onClick={() => setTab('tools')}>Tools</button>
        <button className="mini" onClick={() => load()} title="Refresh">↻</button>
      </div>

      {error && <div className="msg err">{error}</div>}
      {loading && <div className="empty">Loading…</div>}

      {!loading && tab === 'stats' && <Analytics stats={stats} />}

      {!loading && tab === 'queue' && (
        <>
          {pledges.length === 0 && <div className="empty">No pledges yet.</div>}
          {pledges.map((p) => {
            const ded = config.dedications[p.dedication_type] || config.dedications.refuah;
            const before = p.before_minutes || 0;
            const base = p.after_base_minutes || 0;
            const extra = p.after_extra_minutes || 0;

            if (editing === p.id) {
              return (
                <EditPledge
                  key={p.id}
                  pledge={p}
                  onCancel={() => setEditing(null)}
                  onSave={async (fields) => {
                    setError('');
                    try {
                      const r = await post({ action: 'update', id: p.id, ...fields });
                      setPledges((prev) => prev.map((x) => (x.id === p.id ? r.pledge : x)));
                      setEditing(null);
                    } catch (e) { setError(e.message); }
                  }}
                />
              );
            }

            return (
              <div className="card" key={p.id}>
                <div className="card-top">
                  <div>
                    <div className="dedication">{ded.prefix}</div>
                    <div className="name" dir="rtl">{formatRefuahName(p)}</div>
                    {p.refuah_name_english && <div className="name-en">{p.refuah_name_english}</div>}
                  </div>
                  <div className="minutes">
                    <b>{rowExtraMinutes(p)}</b>
                    <small>extra min/wk · {p.weeks} {p.weeks === 1 ? 'wk' : 'wks'}</small>
                  </div>
                </div>

                <div className="ends-row">
                  {before > 0 && <span className="end-pill before">🕯 +{before} early</span>}
                  {extra > 0 && <span className="end-pill after">✦ +{extra} late</span>}
                  {base > 0 && <span className="end-pill baseline">holds til {base}m</span>}
                </div>

                <div className="admin-meta">
                  {p.pledger_name ? `By ${p.pledger_name} · ` : ''}
                  {p.source} · ends {new Date(p.end_date).toLocaleDateString()}
                  {p.email && <> · <span className="admin-email">✉ {p.email}</span></>}
                </div>

                <div className="card-bottom">
                  <span className={`tag ${p.status}`}>{p.status}</span>
                  <div className="row">
                    <button className="mini" onClick={() => setEditing(p.id)}>Edit</button>
                    {p.status !== 'approved' && <button className="mini approve" onClick={() => moderate(p.id, 'approved')}>Approve</button>}
                    {p.status !== 'rejected' && <button className="mini reject" onClick={() => moderate(p.id, 'rejected')}>Hide</button>}
                  </div>
                </div>
              </div>
            );
          })}
        </>
      )}

      {!loading && tab === 'suggestions' && (
        <Suggestions
          items={suggestions}
          onSet={async (id, status) => {
            setError('');
            try {
              await post({ action: 'suggestion', id, status });
              setSuggestions((prev) => prev.map((s) => (s.id === id ? { ...s, status } : s)));
            } catch (e) { setError(e.message); }
          }}
        />
      )}

      {!loading && tab === 'whatsapp' && <WhatsAppComposer pledges={pledges} featured={featured} />}

      {!loading && tab === 'tools' && (
        <Tools
          pledges={pledges}
          adminCode={adminCode}
          featured={featured}
          onFeature={async (payload) => {
            setError('');
            try {
              const r = await post({ action: 'feature', ...payload });
              setFeatured(r.featured);
            } catch (e) { setError(e.message); }
          }}
          onUnfeature={async () => {
            setError('');
            try { await post({ action: 'unfeature' }); setFeatured(null); }
            catch (e) { setError(e.message); }
          }}
          onError={setError}
        />
      )}

      <div className="toolbar">
        <a className="linkbtn" href="/">← Back to the board</a>
        <button className="linkbtn" onClick={signOut}>Sign out</button>
      </div>
    </main>
  );
}

/**
 * Inline editor for one pledge. Sends the same field names the public form
 * sends, so the server runs identical validation on both paths.
 */
function EditPledge({ pledge, onSave, onCancel }) {
  const [name, setName] = useState(pledge.refuah_name || '');
  const [english, setEnglish] = useState(pledge.refuah_name_english || '');
  const [mother, setMother] = useState(pledge.refuah_mother_name || '');
  const [relation, setRelation] = useState(pledge.refuah_relation || 'ben');
  const [dedication, setDedication] = useState(pledge.dedication_type || 'refuah');
  const [tehillim, setTehillim] = useState(pledge.tehillim_chapters || '');
  const [before, setBefore] = useState(pledge.before_minutes || 0);
  const [base, setBase] = useState(pledge.after_base_minutes ?? '');
  const [extra, setExtra] = useState(pledge.after_extra_minutes || 0);
  const [busy, setBusy] = useState(false);
  const [kbdFor, setKbdFor] = useState(null);

  const nameRef = useRef(null);
  const motherRef = useRef(null);
  const caretRef = useRef(null);

  const kbdRef = kbdFor === 'mother' ? motherRef : nameRef;
  const kbdValue = kbdFor === 'mother' ? mother : name;
  const setKbdValue = kbdFor === 'mother' ? setMother : setName;

  useEffect(() => {
    if (caretRef.current != null && kbdRef.current) {
      kbdRef.current.focus();
      const p = caretRef.current;
      kbdRef.current.setSelectionRange(p, p);
      caretRef.current = null;
    }
  }, [name, mother, kbdRef]);

  function insertAtCaret(ch) {
    const el = kbdRef.current;
    const s = el?.selectionStart ?? kbdValue.length;
    const e = el?.selectionEnd ?? kbdValue.length;
    caretRef.current = s + ch.length;
    setKbdValue(kbdValue.slice(0, s) + ch + kbdValue.slice(e));
  }
  function backspace() {
    const el = kbdRef.current;
    const s = el?.selectionStart ?? kbdValue.length;
    const e = el?.selectionEnd ?? kbdValue.length;
    if (s === e) {
      if (s === 0) return;
      caretRef.current = s - 1;
      setKbdValue(kbdValue.slice(0, s - 1) + kbdValue.slice(e));
    } else {
      caretRef.current = s;
      setKbdValue(kbdValue.slice(0, s) + kbdValue.slice(e));
    }
  }

  async function save() {
    setBusy(true);
    await onSave({
      refuahName: name.trim(),
      refuahNameEnglish: english.trim() || null,
      refuahMotherName: mother.trim() || null,
      refuahRelation: relation,
      dedicationType: dedication,
      tehillimChapters: tehillim.trim() || null,
      beforeMinutes: Number(before) || 0,
      afterBaseMinutes: base === '' ? null : Number(base),
      afterExtraMinutes: Number(extra) || 0,
      weeks: pledge.weeks,
    });
    setBusy(false);
  }

  return (
    <div className="card editing">
      <div className="dedication">Editing pledge</div>

      <label htmlFor={`e-name-${pledge.id}`}>Name (Hebrew)</label>
      <input
        id={`e-name-${pledge.id}`} ref={nameRef} type="text" dir="rtl" className="he-input"
        value={name} onChange={(e) => setName(e.target.value)}
      />
      <button type="button" className="kbd-toggle" onClick={() => setKbdFor((v) => (v === 'name' ? null : 'name'))}>
        ⌨ {kbdFor === 'name' ? 'Hide keyboard' : 'Hebrew keyboard'}
      </button>
      {kbdFor === 'name' && (
        <HebrewKeyboard onInsert={insertAtCaret} onBackspace={backspace} onSpace={() => insertAtCaret(' ')} onClose={() => setKbdFor(null)} />
      )}

      <label htmlFor={`e-mother-${pledge.id}`}>Mother&apos;s name</label>
      <div className="relation-row">
        <div className="segment relation-seg">
          {[{ k: 'ben', l: 'בן' }, { k: 'bas', l: 'בת' }].map((r) => (
            <div
              key={r.k} className={`seg ${relation === r.k ? 'active' : ''}`}
              onClick={() => setRelation(r.k)} role="button" tabIndex={0}
              onKeyDown={(e) => e.key === 'Enter' && setRelation(r.k)}
            >
              <span className="he-input" style={{ fontSize: '1.1rem' }}>{r.l}</span>
            </div>
          ))}
        </div>
        <input
          id={`e-mother-${pledge.id}`} ref={motherRef} type="text" dir="rtl" className="he-input"
          value={mother} onChange={(e) => setMother(e.target.value)}
        />
      </div>
      <button type="button" className="kbd-toggle" onClick={() => setKbdFor((v) => (v === 'mother' ? null : 'mother'))}>
        ⌨ {kbdFor === 'mother' ? 'Hide keyboard' : "Hebrew keyboard for mother's name"}
      </button>
      {kbdFor === 'mother' && (
        <HebrewKeyboard onInsert={insertAtCaret} onBackspace={backspace} onSpace={() => insertAtCaret(' ')} onClose={() => setKbdFor(null)} />
      )}

      <label htmlFor={`e-en-${pledge.id}`}>English name</label>
      <input id={`e-en-${pledge.id}`} type="text" value={english} onChange={(e) => setEnglish(e.target.value)} />

      <label>Dedication</label>
      <div className="segment">
        {Object.entries(config.dedications).map(([k, d]) => (
          <div
            key={k} className={`seg ${dedication === k ? 'active' : ''}`}
            onClick={() => setDedication(k)} role="button" tabIndex={0}
            onKeyDown={(e) => e.key === 'Enter' && setDedication(k)}
          >
            {d.label}
          </div>
        ))}
      </div>

      <label htmlFor={`e-teh-${pledge.id}`}>Tehillim taken on</label>
      <input
        id={`e-teh-${pledge.id}`} type="text" maxLength={TEHILLIM_MAX}
        value={tehillim} placeholder="— none —"
        onChange={(e) => setTehillim(e.target.value)}
      />

      <div className="edit-mins">
        <div>
          <label htmlFor={`e-before-${pledge.id}`}>Before (early)</label>
          <input id={`e-before-${pledge.id}`} type="number" min={0} max={180} value={before} onChange={(e) => setBefore(e.target.value)} />
        </div>
        <div>
          <label htmlFor={`e-base-${pledge.id}`}>Usual end</label>
          <input id={`e-base-${pledge.id}`} type="number" min={18} max={180} value={base} placeholder="—" onChange={(e) => setBase(e.target.value)} />
        </div>
        <div>
          <label htmlFor={`e-extra-${pledge.id}`}>On top</label>
          <input id={`e-extra-${pledge.id}`} type="number" min={0} max={180} value={extra} onChange={(e) => setExtra(e.target.value)} />
        </div>
      </div>
      <div className="hint">
        Counted: <b>{(Number(before) || 0) + (Number(extra) || 0)}</b> extra min/week
        {' '}(the usual end time isn&apos;t counted)
      </div>

      <div className="success-actions">
        <button className="btn ghost" onClick={save} disabled={busy}>{busy ? 'Saving…' : 'Save changes'}</button>
        <button className="btn ghost" onClick={onCancel} disabled={busy}>Cancel</button>
      </div>
    </div>
  );
}

