/** Active, approved pledges grouped by name — shared by the tools + composer. */
function useActiveNames(pledges) {
  return useMemo(() => {
    const now = Date.now();
    const map = new Map();
    pledges
      .filter((p) => p.status === 'approved' && new Date(p.end_date).getTime() > now)
      .forEach((p) => {
        const key = `${p.refuah_name}||${p.dedication_type || 'refuah'}`;
        if (!map.has(key)) {
          map.set(key, {
            refuahName: p.refuah_name,
            refuahNameEnglish: p.refuah_name_english || null,
            dedicationType: p.dedication_type || 'refuah',
            minutes: 0, count: 0,
          });
        }
        const e = map.get(key);
        e.minutes += rowExtraMinutes(p); e.count += 1;
      });
    return [...map.values()].sort((a, b) => b.minutes - a.minutes);
  }, [pledges]);
}

/** Generates ready-to-paste text for a WhatsApp Broadcast list. No API needed. */
function WhatsAppComposer({ pledges, featured }) {
  const names = useActiveNames(pledges);
  const [zip, setZip] = useState('');
  const [zmanim, setZmanim] = useState(null);
  const [busy, setBusy] = useState(false);
  const [zErr, setZErr] = useState('');
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    try {
      const saved = JSON.parse(localStorage.getItem('tsb_loc') || 'null');
      if (saved?.zip) { setZip(saved.zip); fetchZmanim(saved.zip); }
    } catch { /* ignore */ }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function fetchZmanim(z) {
    setBusy(true); setZErr('');
    try {
      const res = await fetch(`/api/zmanim?zip=${encodeURIComponent(z)}`, { cache: 'no-store' });
      const j = await res.json();
      if (!res.ok) { setZErr(j.error || 'Could not load zmanim.'); setZmanim(null); }
      else setZmanim(j);
    } catch { setZErr('Could not load zmanim.'); }
    finally { setBusy(false); }
  }

  const text = useMemo(() => {
    const L = [];
    if (zmanim) {
      L.push(`🕯 *Shabbos Zmanim* — ${zmanim.location}`);
      if (zmanim.parasha) L.push(zmanim.parasha.title);
      if (zmanim.candles) L.push(`Candle lighting: ${zmanim.candles.title.replace(/^.*?:\s*/, '')}`);
      if (zmanim.havdalah) L.push(`Motzai Shabbos: ${zmanim.havdalah.title.replace(/^.*?:\s*/, '')}`);
      L.push('');
    }
    if (featured?.refuahName) {
      L.push(`🙏 *Please daven especially for:*`);
      L.push(`${featured.refuahName}${featured.refuahNameEnglish ? ` (${featured.refuahNameEnglish})` : ''}`);
      if (featured.note) L.push(featured.note);
      L.push('');
    }
    const refuah = names.filter((n) => n.dedicationType === 'refuah');
    const zecher = names.filter((n) => n.dedicationType === 'zecher');
    if (refuah.length) {
      L.push('*Tosfos Shabbos this week — lirfuah shleimah:*');
      refuah.forEach((n) => L.push(`• ${n.refuahName}${n.refuahNameEnglish ? ` (${n.refuahNameEnglish})` : ''}`));
      L.push('');
    }
    if (zecher.length) {
      L.push("*L'zecher nishmas:*");
      zecher.forEach((n) => L.push(`• ${n.refuahName}${n.refuahNameEnglish ? ` (${n.refuahNameEnglish})` : ''}`));
      L.push('');
    }
    const origin = typeof window !== 'undefined' ? window.location.origin : '';
    L.push(`Take on a few extra minutes of Shabbos: ${origin}`);
    L.push('');
    L.push(config.lilui.header);
L.push(config.lilui.names[0]);
L.push(config.lilui.names[1]);
    return L.join('\n');
  }, [zmanim, names, featured]);

  async function copy() {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true); setTimeout(() => setCopied(false), 2000);
    } catch {
      setZErr('Could not copy — select the text and copy manually.');
    }
  }

  return (
    <div className="panel rise">
      <h2>This week&apos;s WhatsApp broadcast</h2>
      <p className="sub">Generates text to paste into your WhatsApp Broadcast list. Nothing is sent from here.</p>

      <label htmlFor="wzip">Zmanim location (US ZIP)</label>
      <div className="field-row">
        <input id="wzip" type="text" inputMode="numeric" maxLength={5} value={zip} onChange={(e) => setZip(e.target.value)} placeholder="e.g. 11219" />
        <button type="button" className="mini" onClick={() => fetchZmanim(zip)} disabled={busy}>
          {busy ? '…' : 'Load'}
        </button>
      </div>
      {zErr && <div className="msg err">{zErr}</div>}

      <label htmlFor="wtext" style={{ marginTop: 18 }}>Ready to paste</label>
      <textarea id="wtext" className="broadcast" readOnly value={text} rows={16} />

      <div className="success-actions">
        <button className="btn ghost" onClick={copy}>{copied ? '✓ Copied' : '📋 Copy text'}</button>
        <a className="btn ghost" href={`https://wa.me/?text=${encodeURIComponent(text)}`} target="_blank" rel="noopener noreferrer">
          Open in WhatsApp
        </a>
      </div>
    </div>
  );
}

function Tools({ pledges, adminCode, featured, onFeature, onUnfeature, onError }) {
  const names = useActiveNames(pledges);
  const [sel, setSel] = useState('');
  const [note, setNote] = useState('');
  const [downloading, setDownloading] = useState('');

  async function downloadCsv({ emails, scope }) {
    setDownloading(`${scope}-${emails ? 'e' : 'n'}`);
    onError('');
    try {
      const qs = new URLSearchParams({ scope });
      if (emails) qs.set('emails', '1');
      const res = await fetch(`/api/admin/export?${qs}`, { headers: { 'x-admin-code': adminCode } });
      if (!res.ok) { onError('Export failed.'); return; }
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `tosfos-shabbos-${scope}.csv`;
      document.body.appendChild(a); a.click(); a.remove();
      URL.revokeObjectURL(url);
    } catch {
      onError('Export failed.');
    } finally { setDownloading(''); }
  }

  function feature() {
    const n = names.find((x) => `${x.refuahName}||${x.dedicationType}` === sel);
    if (!n) { onError('Pick a name to feature.'); return; }
    onFeature({
      refuahName: n.refuahName,
      refuahNameEnglish: n.refuahNameEnglish,
      dedicationType: n.dedicationType,
      note: note.trim() || null,
    });
  }

  return (
    <>
      <div className="panel rise">
        <h2>Featured urgent refuah</h2>
        <p className="sub">Spotlights one name at the top of the board.</p>

        {featured?.refuahName ? (
          <div className="featured-now">
            <div>
              <div className="dedication">Currently featured</div>
              <div className="name" dir="rtl">{featured.refuahName}</div>
              {featured.refuahNameEnglish && <div className="name-en">{featured.refuahNameEnglish}</div>}
              {featured.note && <div className="admin-meta">{featured.note}</div>}
            </div>
            <button className="mini reject" onClick={onUnfeature}>Clear</button>
          </div>
        ) : (
          <div className="admin-meta">No name is currently featured.</div>
        )}

        <label htmlFor="featSel">Choose a name</label>
        <select id="featSel" value={sel} onChange={(e) => setSel(e.target.value)}>
          <option value="">— select —</option>
          {names.map((n) => (
            <option key={`${n.refuahName}||${n.dedicationType}`} value={`${n.refuahName}||${n.dedicationType}`}>
              {n.refuahName}{n.refuahNameEnglish ? ` (${n.refuahNameEnglish})` : ''} — {n.dedicationType}
            </option>
          ))}
        </select>

        <label htmlFor="featNote">Short note <span className="opt">— optional</span></label>
        <input id="featNote" type="text" maxLength={200} value={note} onChange={(e) => setNote(e.target.value)} placeholder="e.g. Surgery this Tuesday" />

        <button className="btn" onClick={feature}>Feature this name</button>
      </div>

      <div className="panel rise-2">
        <h2>Export CSV</h2>
        <p className="sub">
          Emails are left out by default so the file is safe to hand to a rav or gabbai.
        </p>
        <div className="success-actions">
          <button className="btn ghost" onClick={() => downloadCsv({ emails: false, scope: 'active' })} disabled={!!downloading}>
            ⬇ Active names
          </button>
          <button className="btn ghost" onClick={() => downloadCsv({ emails: false, scope: 'all' })} disabled={!!downloading}>
            ⬇ All pledges
          </button>
          <button className="btn ghost" onClick={() => downloadCsv({ emails: true, scope: 'all' })} disabled={!!downloading}>
            ⬇ All + emails
          </button>
        </div>
        <div className="hint">Opens in Excel with Hebrew intact (UTF-8 BOM included).</div>
      </div>
    </>
  );
}

/** All analytics derived client-side from the admin payload — no extra query. */
function useAnalytics(pledges) {
  return useMemo(() => {
    const now = Date.now();
    const approved = pledges.filter((p) => p.status === 'approved');
    const active = approved.filter((p) => new Date(p.end_date).getTime() > now);
    const expired = approved.filter((p) => new Date(p.end_date).getTime() <= now);

    // Counted minutes are extra only — the after-Shabbos baseline never counts.
    const minutesActive = active.reduce((s, p) => s + rowExtraMinutes(p), 0);
    const beforeTotal = active.reduce((s, p) => s + (p.before_minutes || 0), 0);
    const afterTotal = active.reduce((s, p) => s + (p.after_extra_minutes || 0), 0);

    const byDedication = { refuah: 0, zecher: 0 };
    active.forEach((p) => { byDedication[p.dedication_type || 'refuah'] += 1; });

    const withBefore = active.filter((p) => (p.before_minutes || 0) > 0).length;
    const withAfter = active.filter((p) => (p.after_extra_minutes || 0) > 0).length;
    const withBoth = active.filter(
      (p) => (p.before_minutes || 0) > 0 && (p.after_extra_minutes || 0) > 0
    ).length;

    const emails = new Set(pledges.filter((p) => p.email).map((p) => p.email));

    const nameMap = new Map();
    active.forEach((p) => {
      const key = `${p.refuah_name}||${p.dedication_type || 'refuah'}`;
      if (!nameMap.has(key)) {
        nameMap.set(key, { name: p.refuah_name, ded: p.dedication_type || 'refuah', count: 0, minutes: 0 });
      }
      const e = nameMap.get(key);
      e.count += 1; e.minutes += rowExtraMinutes(p);
    });
    const topNames = [...nameMap.values()].sort((a, b) => b.minutes - a.minutes).slice(0, 6);

    const days = [];
    const dayMs = 86400000;
    const today = new Date(); today.setHours(0, 0, 0, 0);
    for (let i = 29; i >= 0; i--) {
      const d = new Date(today.getTime() - i * dayMs);
      days.push({ d, label: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }), n: 0 });
    }
    pledges.forEach((p) => {
      const c = new Date(p.created_at); c.setHours(0, 0, 0, 0);
      const idx = days.findIndex((x) => x.d.getTime() === c.getTime());
      if (idx >= 0) days[idx].n += 1;
    });

    const avg = active.length ? Math.round(minutesActive / active.length) : 0;
    const weeksAvg = active.length
      ? (active.reduce((s, p) => s + (p.weeks || 0), 0) / active.length).toFixed(1)
      : '0';

    return {
      totalPledges: pledges.length,
      approved: approved.length,
      active: active.length,
      expired: expired.length,
      hidden: pledges.filter((p) => p.status === 'rejected').length,
      minutesActive, beforeTotal, afterTotal,
      byDedication, withBefore, withAfter, withBoth,
      emailCount: emails.size,
      uniqueNames: nameMap.size,
      avg, weeksAvg,
      topNames, days,
    };
  }, [pledges]);
}

function Analytics({ stats }) {
  const maxDay = Math.max(1, ...stats.days.map((d) => d.n));
  const dedTotal = stats.byDedication.refuah + stats.byDedication.zecher || 1;
  const refuahPct = Math.round((stats.byDedication.refuah / dedTotal) * 100);

  return (
    <>
      <div className="stat-grid rise">
        <Stat label="Extra minutes / week (added)" value={stats.minutesActive.toLocaleString()} hero />
        <Stat label="Active pledges" value={stats.active} />
        <Stat label="Names" value={stats.uniqueNames} />
        <Stat label="Total pledges" value={stats.totalPledges} />
        <Stat label="Avg / pledge" value={`${stats.avg} min`} />
        <Stat label="Avg weeks" value={stats.weeksAvg} />
        <Stat label="Expired" value={stats.expired} />
        <Stat label="Hidden" value={stats.hidden} />
        <Stat label="Email signups" value={stats.emailCount} />
      </div>

      <div className="panel rise-2">
        <h2>Both ends <span className="h2-note">— added minutes only</span></h2>
        <div className="split-bar" aria-hidden="true">
          <span className="sb-before" style={{ width: `${(stats.beforeTotal / Math.max(1, stats.minutesActive)) * 100}%` }} />
          <span className="sb-after" style={{ width: `${(stats.afterTotal / Math.max(1, stats.minutesActive)) * 100}%` }} />
        </div>
        <div className="split-legend">
          <span><i className="dot before" /> Before Shabbos (early) — <b>{stats.beforeTotal}</b> min ({stats.withBefore} pledges)</span>
          <span><i className="dot after" /> After Shabbos (on top) — <b>{stats.afterTotal}</b> min ({stats.withAfter} pledges)</span>
          <span className="muted">{stats.withBoth} pledged both ends</span>
        </div>
      </div>

      <div className="panel rise-2">
        <h2>Dedications</h2>
        <div className="split-bar" aria-hidden="true">
          <span className="sb-refuah" style={{ width: `${refuahPct}%` }} />
          <span className="sb-zecher" style={{ width: `${100 - refuahPct}%` }} />
        </div>
        <div className="split-legend">
          <span><i className="dot refuah" /> Lirfuah shleimah — <b>{stats.byDedication.refuah}</b></span>
          <span><i className="dot zecher" /> L&apos;zecher nishmas — <b>{stats.byDedication.zecher}</b></span>
        </div>
      </div>

      <div className="panel rise-2">
        <h2>New pledges — last 30 days</h2>
        <svg className="spark" viewBox={`0 0 ${stats.days.length * 10} 40`} preserveAspectRatio="none" role="img" aria-label="Bar chart of new pledges per day over the last 30 days">
          <defs>
            <linearGradient id="goldbar" x1="0" y1="1" x2="0" y2="0">
              <stop offset="0%" stopColor="#9A7B33" />
              <stop offset="100%" stopColor="#EBCF8A" />
            </linearGradient>
          </defs>
          {stats.days.map((d, i) => {
            const h = d.n === 0 ? 0.6 : (d.n / maxDay) * 34;
            return <rect key={i} x={i * 10 + 2} y={38 - h} width="6" height={h} rx="1.5" fill={d.n === 0 ? 'rgba(201,163,78,.18)' : 'url(#goldbar)'}><title>{`${d.label}: ${d.n}`}</title></rect>;
          })}
        </svg>
        <div className="spark-axis">
          <span>{stats.days[0]?.label}</span>
          <span>{stats.days[stats.days.length - 1]?.label}</span>
        </div>
      </div>

      <div className="panel rise-2">
        <h2>Most pledged for</h2>
        {stats.topNames.length === 0 ? (
          <div className="empty">No active pledges yet.</div>
        ) : (
          <ol className="toplist">
            {stats.topNames.map((t) => (
              <li key={`${t.name}-${t.ded}`}>
                <span className="tl-name" dir="rtl">{t.name}</span>
                <span className="tl-meta">
                  <span className={`tag ${t.ded === 'refuah' ? 'approved' : 'pending'}`}>
                    {t.ded === 'refuah' ? 'refuah' : 'zecher'}
                  </span>
                  <b>{t.minutes}</b> min · {t.count} {t.count === 1 ? 'pledge' : 'pledges'}
                </span>
              </li>
            ))}
          </ol>
        )}
      </div>
    </>
  );
}

function Stat({ label, value, hero }) {
  return (
    <div className={`stat ${hero ? 'hero-stat' : ''}`}>
      <div className="stat-val">{value}</div>
      <div className="stat-lbl">{label}</div>
    </div>
  );
}

import { NextResponse } from 'next/server';
import {
  listAll, setStatus, getSetting, setSetting,
  listSuggestions, setSuggestionStatus, updatePledge,
} from '@/lib/db';
import { validatePledgeFields } from '@/lib/pledges';
import { FEATURED_KEY } from '@/lib/settings';

export const dynamic = 'force-dynamic';

const ADMIN_CODE = process.env.ADMIN_CODE || '';

// The admin code may arrive as an `x-admin-code` header (GET) or in the JSON
// body (POST). If ADMIN_CODE is unset the admin surface is locked (deny all)
// rather than left open.
function authorized(provided) {
  if (!ADMIN_CODE) return false;
  return String(provided ?? '') === ADMIN_CODE;
}

/**
 * GET /api/admin  (auth via x-admin-code header)
 * Every pledge, newest first, plus current settings.
 */
export async function GET(request) {
  if (!authorized(request.headers.get('x-admin-code'))) {
    return NextResponse.json({ error: 'Unauthorized.' }, { status: 401 });
  }
  try {
    // A missing table (migration not yet run) shouldn't take down the panel.
    const [pledges, featured, suggestions] = await Promise.all([
      listAll(),
      getSetting(FEATURED_KEY, null).catch(() => null),
      listSuggestions().catch(() => []),
    ]);
    return NextResponse.json({ pledges, featured, suggestions });
  } catch {
    return NextResponse.json({ error: 'Could not load pledges.' }, { status: 500 });
  }
}

/**
 * POST /api/admin
 *   { adminCode, action: 'moderate', id, status }
 *   { adminCode, action: 'feature', refuahName, refuahNameEnglish?, dedicationType?, note? }
 *   { adminCode, action: 'unfeature' }
 * `action` defaults to 'moderate' for backward compatibility.
 */
export async function POST(request) {
  let body;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid request body.' }, { status: 400 });
  }

  if (!authorized(body.adminCode)) {
    return NextResponse.json({ error: 'Unauthorized.' }, { status: 401 });
  }

  const action = String(body.action || 'moderate');

  if (action === 'unfeature') {
    try {
      await setSetting(FEATURED_KEY, null);
      return NextResponse.json({ featured: null });
    } catch {
      return NextResponse.json({ error: 'Could not clear the spotlight.' }, { status: 500 });
    }
  }

  if (action === 'update') {
    const id = String(body.id ?? '').trim();
    if (!id) return NextResponse.json({ error: 'Missing pledge id.' }, { status: 400 });

    // Exactly the rules the public form enforces — no community code needed,
    // since the admin code already authorised this request.
    const result = validatePledgeFields(body);
    if (!result.ok) {
      return NextResponse.json({ error: result.error }, { status: 400 });
    }

    try {
      const updated = await updatePledge(id, result.value);
      if (!updated) return NextResponse.json({ error: 'Pledge not found.' }, { status: 404 });
      return NextResponse.json({ pledge: updated });
    } catch {
      return NextResponse.json({ error: 'Could not update pledge.' }, { status: 500 });
    }
  }

  if (action === 'suggestion') {
    const id = String(body.id ?? '').trim();
    const status = String(body.status ?? '').trim();
    if (!id) return NextResponse.json({ error: 'Missing suggestion id.' }, { status: 400 });
    if (!['new', 'handled', 'dismissed'].includes(status)) {
      return NextResponse.json(
        { error: 'Status must be one of: new, handled, dismissed.' },
        { status: 400 }
      );
    }
    try {
      const updated = await setSuggestionStatus(id, status);
      if (!updated) return NextResponse.json({ error: 'Suggestion not found.' }, { status: 404 });
      return NextResponse.json({ suggestion: updated });
    } catch {
      return NextResponse.json({ error: 'Could not update suggestion.' }, { status: 500 });
    }
  }

  if (action === 'feature') {
    const refuahName = String(body.refuahName ?? '').trim();
    if (!refuahName) {
      return NextResponse.json({ error: 'Missing name to feature.' }, { status: 400 });
    }
    if (refuahName.length > 120) {
      return NextResponse.json({ error: 'Name is too long.' }, { status: 400 });
    }
    const note = String(body.note ?? '').trim().slice(0, 200) || null;
    const dedicationType = body.dedicationType === 'zecher' ? 'zecher' : 'refuah';
    const featured = {
      refuahName,
      refuahNameEnglish: String(body.refuahNameEnglish ?? '').trim() || null,
      dedicationType,
      note,
      setAt: new Date().toISOString(),
    };
    try {
      await setSetting(FEATURED_KEY, featured);
      return NextResponse.json({ featured });
    } catch {
      return NextResponse.json({ error: 'Could not set the spotlight.' }, { status: 500 });
    }
  }

  // --- moderate ---
  const id = String(body.id ?? '').trim();
  const status = String(body.status ?? '').trim();

  if (!id) return NextResponse.json({ error: 'Missing pledge id.' }, { status: 400 });
  if (status !== 'approved' && status !== 'rejected') {
    return NextResponse.json(
      { error: 'Status must be one of: approved, rejected.' },
      { status: 400 }
    );
  }

  try {
    const updated = await setStatus(id, status);
    if (!updated) return NextResponse.json({ error: 'Pledge not found.' }, { status: 404 });
    return NextResponse.json({ pledge: updated });
  } catch {
    return NextResponse.json({ error: 'Could not update pledge.' }, { status: 500 });
  }
}

// Pledge domain logic: validation, expiry computation, and wall grouping.
// Enforced server-side on every write (the client UI mirrors them only for UX).
//
// A pledge has two independent ends:
//   BEFORE Shabbos — accepting Shabbos early by `beforeMinutes`.
//   AFTER  Shabbos — holding Shabbos until `afterBaseMinutes` past shkia,
//                    plus `afterExtraMinutes` added on top.
// A pledge may be before-only, after-only, or both. The stored
// `duration_minutes` is the TOTAL of all pledged minutes.

export const COMMUNITY_CODE = process.env.COMMUNITY_CODE || '235';

export const FIELD_MIN = 18; // minimum for the after base
export const FIELD_MAX = 180; // max for any single field
export const WEEKS_MIN = 1;
export const WEEKS_MAX = 4;

export const AFTER_PRESETS = [50, 60, 72];
export const AFTER_EXTRA_DEFAULT = 10;
export const DEDICATION_TYPES = ['refuah', 'zecher'];
export const TEHILLIM_MAX = 200;

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** Next upcoming Friday at 00:00 UTC ("upcoming" = today if today is Friday). */
export function nextFriday(from = new Date()) {
  const d = new Date(Date.UTC(from.getUTCFullYear(), from.getUTCMonth(), from.getUTCDate()));
  const delta = (5 - d.getUTCDay() + 7) % 7;
  d.setUTCDate(d.getUTCDate() + delta);
  return d;
}

/** start = next upcoming Friday; end = start + weeks*7 days. */
export function computeWindow(weeks, from = new Date()) {
  const startDate = nextFriday(from);
  const endDate = new Date(startDate);
  endDate.setUTCDate(endDate.getUTCDate() + weeks * 7);
  return { startDate, endDate };
}

// COUNTING MODEL — "extra only".
// `afterBaseMinutes` is the person's USUAL Shabbos end time (their baseline —
// what they keep anyway), so it is stored and displayed for context but is
// NEVER counted. Only genuinely added minutes count:
//     extra = beforeMinutes + afterExtraMinutes
// e.g. 72 base + 10 on top + 10 early = 20 extra (not 92).

/** Counted (extra) minutes per week for a set of components. */
export function pledgeExtra({ beforeMinutes = 0, afterExtraMinutes = 0 }) {
  return (beforeMinutes || 0) + (afterExtraMinutes || 0);
}

/** Counted (extra) minutes for a stored row (snake_case). */
export function rowExtraMinutes(p) {
  if (!p) return 0;
  // Deliberately no fallback to the legacy duration_minutes column: for rows
  // written before this model it held baseline+extra, which would over-count.
  return (p.before_minutes || 0) + (p.after_extra_minutes || 0);
}

/** The person's usual Shabbos end time, in minutes past shkia (context only). */
export function rowBaseline(p) {
  return p?.after_base_minutes ?? null;
}

/**
 * Render a name as "[name] בן/בת [mother]" when a mother's name is on file.
 * Older pledges often have the full construction typed into refuah_name
 * already, so with no mother's name we return the name untouched.
 * Accepts either a DB row (snake_case) or form values (camelCase).
 */
export function formatRefuahName(p) {
  if (!p) return '';
  const name = p.refuah_name ?? p.refuahName ?? '';
  const mother = p.refuah_mother_name ?? p.refuahMotherName ?? null;
  const relation = p.refuah_relation ?? p.refuahRelation ?? 'ben';
  if (!mother) return name;
  return `${name} ${relation === 'bas' ? 'בת' : 'בן'} ${mother}`;
}

/**
 * Pull recognisable perek numbers out of a free-text Tehillim commitment, so
 * "20, 30, 121" can be rendered as links. Anything outside 1–150 isn't a perek,
 * and text with no numbers at all ("כל ספר א") yields none — callers then show
 * the raw text instead rather than dropping what the person actually wrote.
 * Returns numbers in the order written, de-duplicated.
 */
export function parseTehillim(text) {
  if (!text) return [];
  const seen = new Set();
  for (const m of String(text).matchAll(/\d+/g)) {
    const n = Number(m[0]);
    if (n >= 1 && n <= 150) seen.add(n);
  }
  return Array.from(seen);
}

function intOrNull(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isInteger(n) ? n : NaN;
}

/**
 * Validate and normalize an incoming pledge payload.
 * Returns { ok: true, value } or { ok: false, error, code?, spam? }.
 */
export function validatePledge(input, opts = {}) {
  const body = input || {};

  // 0. Spam honeypot — a hidden field real users never fill.
  if (String(body.hp_field ?? '').trim()) {
    return { ok: false, error: 'Submission could not be processed.', spam: true };
  }

  // 1. Community code gate.
  const code = String(body.communityCode ?? body.code ?? '').trim();
  if (code !== COMMUNITY_CODE) {
    return { ok: false, error: 'Invalid community code.', code: 'BAD_CODE' };
  }

  return validatePledgeFields(body, opts);
}

/**
 * Field-level validation, with no community-code check. Shared by the public
 * form (via validatePledge) and the admin edit, so both enforce identical rules.
 */
export function validatePledgeFields(input, opts = {}) {
  const now = opts.now || new Date();
  const body = input || {};

  // 2. refuahName required.
  const refuahName = String(body.refuahName ?? '').trim();
  if (!refuahName) return { ok: false, error: 'A name for the dedication is required.' };
  if (refuahName.length > 120) return { ok: false, error: 'Name is too long.' };

  // 3. refuahNameEnglish optional.
  const englishRaw = String(body.refuahNameEnglish ?? '').trim();
  const refuahNameEnglish = englishRaw || null;
  if (refuahNameEnglish && refuahNameEnglish.length > 120) {
    return { ok: false, error: 'English name is too long.' };
  }

  // 4. dedicationType.
  const dedicationType = String(body.dedicationType ?? 'refuah').trim();
  if (!DEDICATION_TYPES.includes(dedicationType)) {
    return { ok: false, error: 'Invalid dedication type.' };
  }

  // 4b. Mother's name + ben/bas — what the Mi Shebeirach needs. Optional, so
  // older pledges and l'zecher pledges still validate.
  const motherRaw = String(body.refuahMotherName ?? '').trim();
  const refuahMotherName = motherRaw || null;
  if (refuahMotherName && refuahMotherName.length > 120) {
    return { ok: false, error: "Mother's name is too long." };
  }
  const relRaw = String(body.refuahRelation ?? '').trim();
  let refuahRelation = relRaw || null;
  if (refuahRelation && !['ben', 'bas'].includes(refuahRelation)) {
    return { ok: false, error: 'Relation must be ben or bas.' };
  }
  // A mother's name is only meaningful alongside ben/bas; default to ben so the
  // name still renders rather than silently dropping the mother's name.
  if (refuahMotherName && !refuahRelation) refuahRelation = 'ben';

  // 4c. Tehillim the pledger is taking on. Optional and free-text — this is a
  // personal kabbalah, not a fixed list, so we store what they wrote.
  const tehillimRaw = String(body.tehillimChapters ?? '').trim();
  const tehillimChapters = tehillimRaw || null;
  if (tehillimChapters && tehillimChapters.length > TEHILLIM_MAX) {
    return { ok: false, error: 'The Tehillim you entered is too long.' };
  }

  // 5. AFTER Shabbos: base (optional) + extra on top.
  const afterBaseRaw = intOrNull(body.afterBaseMinutes);
  if (Number.isNaN(afterBaseRaw)) {
    return { ok: false, error: 'After-Shabbos minutes must be a whole number.' };
  }
  const afterBaseMinutes = afterBaseRaw;
  if (afterBaseMinutes !== null && (afterBaseMinutes < FIELD_MIN || afterBaseMinutes > FIELD_MAX)) {
    return {
      ok: false,
      error: `Holding Shabbos later must be between ${FIELD_MIN} and ${FIELD_MAX} minutes.`,
    };
  }

  const afterExtraRaw = intOrNull(body.afterExtraMinutes);
  if (Number.isNaN(afterExtraRaw)) {
    return { ok: false, error: 'The added minutes must be a whole number.' };
  }
  let afterExtraMinutes = afterExtraRaw === null ? 0 : afterExtraRaw;
  if (afterExtraMinutes < 0 || afterExtraMinutes > FIELD_MAX) {
    return { ok: false, error: `Added minutes must be between 0 and ${FIELD_MAX}.` };
  }
  // "Add on top" only means something when there's an after-Shabbos pledge.
  if (afterBaseMinutes === null && afterExtraMinutes > 0) {
    return {
      ok: false,
      error: 'Choose how late you hold Shabbos before adding minutes on top.',
    };
  }

  // 6. BEFORE Shabbos: optional early acceptance.
  const beforeRaw = intOrNull(body.beforeMinutes);
  if (Number.isNaN(beforeRaw)) {
    return { ok: false, error: 'Early minutes must be a whole number.' };
  }
  const beforeMinutes = beforeRaw === null ? 0 : beforeRaw;
  if (beforeMinutes < 0 || beforeMinutes > FIELD_MAX) {
    return { ok: false, error: `Early minutes must be between 0 and ${FIELD_MAX}.` };
  }

  // 7. A pledge must actually add time. The after-Shabbos base is the person's
  // usual end time, so on its own it adds nothing.
  if (beforeMinutes + afterExtraMinutes === 0) {
    return {
      ok: false,
      error:
        'Please add at least a minute — either on top of your usual Shabbos end time, or before Shabbos.',
    };
  }

  // 8. weeks.
  const weeks = Number(body.weeks);
  if (!Number.isInteger(weeks)) return { ok: false, error: 'Weeks must be a whole number.' };
  if (weeks < WEEKS_MIN || weeks > WEEKS_MAX) {
    return { ok: false, error: `Weeks must be between ${WEEKS_MIN} and ${WEEKS_MAX}.` };
  }

  // 9. pledgerName optional.
  const pledgerRaw = String(body.pledgerName ?? '').trim();
  const pledgerName = pledgerRaw || null;
  if (pledgerName && pledgerName.length > 120) return { ok: false, error: 'Your name is too long.' };

  // 10. email optional (kept private).
  const emailRaw = String(body.email ?? '').trim().toLowerCase();
  let email = null;
  if (emailRaw) {
    if (emailRaw.length > 254 || !EMAIL_RE.test(emailRaw)) {
      return { ok: false, error: 'Please enter a valid email address.' };
    }
    email = emailRaw;
  }

  const { startDate, endDate } = computeWindow(weeks, now);
  // Stored duration_minutes is the COUNTED (extra) total, not baseline+extra.
  const durationMinutes = pledgeExtra({ beforeMinutes, afterExtraMinutes });

  return {
    ok: true,
    value: {
      refuahName,
      refuahNameEnglish,
      refuahMotherName,
      refuahRelation,
      dedicationType,
      tehillimChapters,
      beforeMinutes,
      afterBaseMinutes,
      afterExtraMinutes,
      durationMinutes, // stored total
      weeks,
      pledgerName,
      email,
      startDate,
      endDate,
    },
  };
}

/**
 * Group approved pledges for the wall by refuah name + dedication type.
 * Carries a breakdown so cards can show both ends. Email is never surfaced.
 */
export function groupForWall(pledges) {
  const groups = new Map();

  for (const p of pledges || []) {
    const dedication = p.dedication_type || 'refuah';
    // Mother's name is part of the identity — two people can share a first name.
    const key = `${p.refuah_name}�${p.refuah_mother_name || ''}�${dedication}`;
    if (!groups.has(key)) {
      groups.set(key, {
        refuahName: p.refuah_name,
        refuahNameEnglish: p.refuah_name_english || null,
        refuahMotherName: p.refuah_mother_name || null,
        refuahRelation: p.refuah_relation || null,
        displayName: formatRefuahName(p),
        dedicationType: dedication,
        totalMinutesPerWeek: 0, // COUNTED extra only
        beforeMinutes: 0,
        afterExtraMinutes: 0,
        // Baselines vary per person, so summing them would be meaningless —
        // carry the range instead, purely as context.
        baselineMin: null,
        baselineMax: null,
        pledgeCount: 0,
        nearestEnd: null,
        pledgers: [],
        // Tehillim is per pledge, but a card is a whole name-group — so carry
        // every distinct commitment made for this name, attributed where the
        // pledger gave a name. Empty when nobody took Tehillim on.
        tehillim: [],
      });
    }
    const g = groups.get(key);
    g.totalMinutesPerWeek += rowExtraMinutes(p);
    g.beforeMinutes += p.before_minutes || 0;
    g.afterExtraMinutes += p.after_extra_minutes || 0;
    const base = p.after_base_minutes;
    if (base != null) {
      g.baselineMin = g.baselineMin === null ? base : Math.min(g.baselineMin, base);
      g.baselineMax = g.baselineMax === null ? base : Math.max(g.baselineMax, base);
    }
    g.pledgeCount += 1;
    if (!g.refuahNameEnglish && p.refuah_name_english) g.refuahNameEnglish = p.refuah_name_english;
    // Prefer whichever record actually carries the mother's name.
    if (!g.refuahMotherName && p.refuah_mother_name) {
      g.refuahMotherName = p.refuah_mother_name;
      g.refuahRelation = p.refuah_relation || 'ben';
      g.displayName = formatRefuahName(p);
    }
    const end = new Date(p.end_date);
    if (g.nearestEnd === null || end < g.nearestEnd) g.nearestEnd = end;
    if (p.pledger_name) g.pledgers.push(p.pledger_name);

    const tehillim = (p.tehillim_chapters || '').trim();
    // Two people who both took "20, 30" shouldn't print twice — but keep an
    // attributed entry over an anonymous duplicate, so credit isn't lost.
    if (tehillim) {
      const dupe = g.tehillim.find((t) => t.text === tehillim);
      if (!dupe) g.tehillim.push({ text: tehillim, pledger: p.pledger_name || null });
      else if (!dupe.pledger && p.pledger_name) dupe.pledger = p.pledger_name;
    }
  }

  const list = Array.from(groups.values()).map((g) => ({
    ...g,
    nearestEnd: g.nearestEnd ? g.nearestEnd.toISOString() : null,
  }));

  list.sort((a, b) => {
    if (b.totalMinutesPerWeek !== a.totalMinutesPerWeek) {
      return b.totalMinutesPerWeek - a.totalMinutesPerWeek;
    }
    if (!a.nearestEnd) return 1;
    if (!b.nearestEnd) return -1;
    return new Date(a.nearestEnd) - new Date(b.nearestEnd);
  });

  return list;
}

/** Sum of all pledged minutes-per-week across groups. */
export function totalMinutesPerWeek(groups) {
  return (groups || []).reduce((s, g) => s + (g.totalMinutesPerWeek || 0), 0);
}

import { getSupabase, isSupabaseConfigured } from './supabase';

// Data-access layer for pledges.
//
// PRODUCTION: backed by Supabase Postgres (see supabase/migrations).
// LOCAL DEV FALLBACK: if SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY are unset, an
// in-memory store is used so the app runs with `npm run dev` out of the box.
// The fallback is process-lifetime only and is NEVER used when Supabase env
// vars are present (including on Vercel).

const TABLE = 'pledges';
export const VALID_STATUSES = ['pending', 'approved', 'rejected'];

// ---- In-memory dev fallback -------------------------------------------------
const mem = (globalThis.__pledgeMem ||= { rows: [] });

function memId() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

// ---- Row mapping ------------------------------------------------------------
function toRow(value, { status, source }) {
  return {
    refuah_name: value.refuahName,
    refuah_name_english: value.refuahNameEnglish,
    refuah_mother_name: value.refuahMotherName ?? null,
    refuah_relation: value.refuahRelation ?? null,
    dedication_type: value.dedicationType || 'refuah',
    tehillim_chapters: value.tehillimChapters ?? null,
    before_minutes: value.beforeMinutes || 0,
    after_base_minutes: value.afterBaseMinutes ?? null,
    after_extra_minutes: value.afterExtraMinutes || 0,
    duration_minutes: value.durationMinutes, // stored total (both ends)
    weeks: value.weeks,
    pledger_name: value.pledgerName,
    email: value.email || null,
    start_date: value.startDate.toISOString(),
    end_date: value.endDate.toISOString(),
    status,
    source,
  };
}

/** Strip private fields for any public-facing payload. */
export function toPublic(row) {
  if (!row) return row;
  const { email, ...rest } = row;
  return rest;
}

// ---- Public API -------------------------------------------------------------

export async function insertPledge(value, { status = 'approved', source = 'web' } = {}) {
  const supabase = getSupabase();
  const row = toRow(value, { status, source });

  if (!supabase) {
    const stored = { id: memId(), created_at: new Date().toISOString(), reminder_sent_at: null, ...row };
    mem.rows.push(stored);
    return stored;
  }

  const { data, error } = await supabase.from(TABLE).insert(row).select().single();
  if (error) throw new Error(error.message);
  return data;
}

/** Approved, not-yet-expired pledges for the public wall. */
export async function listApprovedActive(now = new Date()) {
  const supabase = getSupabase();
  const nowIso = now.toISOString();

  if (!supabase) {
    return mem.rows
      .filter((r) => r.status === 'approved' && r.end_date > nowIso)
      .sort((a, b) => new Date(a.end_date) - new Date(b.end_date));
  }

  const { data, error } = await supabase
    .from(TABLE)
    .select('*')
    .eq('status', 'approved')
    .gt('end_date', nowIso)
    .order('end_date', { ascending: true });
  if (error) throw new Error(error.message);
  return data || [];
}

/** All pledges, newest first — for the admin moderation queue. */
export async function listAll() {
  const supabase = getSupabase();

  if (!supabase) {
    return [...mem.rows].sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
  }

  const { data, error } = await supabase
    .from(TABLE)
    .select('*')
    .order('created_at', { ascending: false });
  if (error) throw new Error(error.message);
  return data || [];
}

/** Update a pledge's moderation status. */
export async function setStatus(id, status) {
  if (!VALID_STATUSES.includes(status)) throw new Error('Invalid status.');
  const supabase = getSupabase();

  if (!supabase) {
    const row = mem.rows.find((r) => r.id === id);
    if (!row) return null;
    row.status = status;
    return row;
  }

  const { data, error } = await supabase
    .from(TABLE)
    .update({ status })
    .eq('id', id)
    .select()
    .single();
  if (error) {
    if (error.code === 'PGRST116') return null;
    throw new Error(error.message);
  }
  return data;
}

/**
 * Admin edit: overwrite a pledge's editable fields. `value` comes from the same
 * validator the public form uses, so the rules can't drift apart. The pledge's
 * dates, status, source and email are deliberately untouched.
 */
export async function updatePledge(id, value) {
  const patch = {
    refuah_name: value.refuahName,
    refuah_name_english: value.refuahNameEnglish,
    refuah_mother_name: value.refuahMotherName ?? null,
    refuah_relation: value.refuahRelation ?? null,
    dedication_type: value.dedicationType || 'refuah',
    tehillim_chapters: value.tehillimChapters ?? null,
    before_minutes: value.beforeMinutes || 0,
    after_base_minutes: value.afterBaseMinutes ?? null,
    after_extra_minutes: value.afterExtraMinutes || 0,
    duration_minutes: value.durationMinutes,
  };

  const supabase = getSupabase();

  if (!supabase) {
    const row = mem.rows.find((r) => r.id === id);
    if (!row) return null;
    Object.assign(row, patch);
    return row;
  }

  const { data, error } = await supabase
    .from(TABLE)
    .update(patch)
    .eq('id', id)
    .select()
    .single();
  if (error) {
    if (error.code === 'PGRST116') return null;
    throw new Error(error.message);
  }
  return data;
}

/**
 * Approved pledges with an email, ending within `windowHours`, that haven't
 * been reminded yet. Used by the reminder cron.
 */
export async function listPledgesNeedingReminder(now = new Date(), windowHours = 36) {
  const nowIso = now.toISOString();
  const untilIso = new Date(now.getTime() + windowHours * 3600 * 1000).toISOString();
  const supabase = getSupabase();

  if (!supabase) {
    return mem.rows.filter(
      (r) =>
        r.status === 'approved' &&
        r.email &&
        !r.reminder_sent_at &&
        r.end_date > nowIso &&
        r.end_date <= untilIso
    );
  }

  const { data, error } = await supabase
    .from(TABLE)
    .select('*')
    .eq('status', 'approved')
    .not('email', 'is', null)
    .is('reminder_sent_at', null)
    .gt('end_date', nowIso)
    .lte('end_date', untilIso);
  if (error) throw new Error(error.message);
  return data || [];
}

/** Mark a pledge's reminder as sent so it isn't emailed twice. */
export async function markReminderSent(id, now = new Date()) {
  const supabase = getSupabase();
  const stamp = now.toISOString();

  if (!supabase) {
    const row = mem.rows.find((r) => r.id === id);
    if (row) row.reminder_sent_at = stamp;
    return;
  }

  const { error } = await supabase.from(TABLE).update({ reminder_sent_at: stamp }).eq('id', id);
  if (error) throw new Error(error.message);
}

