// ---- Settings (key/value) ---------------------------------------------------

const SETTINGS_TABLE = 'app_settings';
const memSettings = (globalThis.__pledgeSettings ||= {});

/** Read a setting's value, or `fallback` if unset. */
export async function getSetting(key, fallback = null) {
  const supabase = getSupabase();

  if (!supabase) {
    return key in memSettings ? memSettings[key] : fallback;
  }

  const { data, error } = await supabase
    .from(SETTINGS_TABLE)
    .select('value')
    .eq('key', key)
    .maybeSingle();
  if (error) throw new Error(error.message);
  return data ? data.value : fallback;
}

/** Upsert a setting. Passing null removes it. */
export async function setSetting(key, value) {
  const supabase = getSupabase();

  if (!supabase) {
    if (value === null) delete memSettings[key];
    else memSettings[key] = value;
    return value;
  }

  if (value === null) {
    const { error } = await supabase.from(SETTINGS_TABLE).delete().eq('key', key);
    if (error) throw new Error(error.message);
    return null;
  }

  const { error } = await supabase
    .from(SETTINGS_TABLE)
    .upsert({ key, value, updated_at: new Date().toISOString() }, { onConflict: 'key' });
  if (error) throw new Error(error.message);
  return value;
}

